INSERT INTO public.findit_challenges(challenge_id,name,description,active) VALUES ('C038','A Tower of Four Things','Safely stack four lightweight objects into a tower and photograph it.',true),('C039','Something Red and Round','Find and photograph something that is both red and round.',true),('C040','Something Blue and Square','Find and photograph something that is both blue and square.',true),('C041','More Than Four Legs','Find and photograph something with more than four legs.',true),('C042','Something That Beeps','Photograph an everyday object that makes a beeping sound. You do not need to activate it.',true),('C043','Something That Needs Repairing','Photograph something that needs repairing, without handling anything unsafe.',true) ON CONFLICT (challenge_id) DO NOTHING;